-- REM-A7-PAPERS-1 (2026-10-26, remediation agent rem-a7 fork F4; charter pillars research and reach; agent_issues 100523 and 100575, owner tasks of the papers cluster).
-- Both issues stood on a born-superseded placeholder probe (VACUOUS-PROBE-V3-1) that can never pass, so neither could close although the conditions they name were measured as met on 2026-10-26:
--   * 100523 (gap C-01, D1 body truncation, 'make DOIs the canonical full text'): the seven records of the audit's table are complete on living-paper, link their full text by r2_path and pdf_path, D1 shows no length cap,
--     and DOIs as the canonical source is superseded by NOZ-DOI-1 (0 of 704 published rows carry a registry identifier). The new probe is a d1-query@living-paper contract that measures those facts and fails when a record is cut.
--   * 100575 (paper versioning on papers.qnfo.org): the reader fix is live (qnfo-gateway 3.43.x reads paper_version_history; the snapshot page carries the capture-date caption). The new probe is a runner-https contract on a stored snapshot.
--   * fm-reader-history-navigation (the detector of that fix) samples one paper that was quarantined on 2026-10-25 and answered 404 then; fm-reader-history-navigation-control is added on a stable published control paper (additive, nothing is hidden).
-- The finding of each issue is staged as issue_triage.close_evidence (the auto-close trigger keeps existing evidence and closes the issue on the first passing verification); the triage state is not changed here.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET verify_probe = 'SELECT ''closed'' AS expected, (SELECT CASE WHEN status IN (''closed'', ''resolved'') THEN ''closed'' ELSE NULL END FROM agent_issues WHERE id = 100523) AS observed', verify_transport = 'd1-query', status = 'superseded', last_verdict = 'superseded:rollback REM-A7-PAPERS-1', module = 'probe-template-v3-generic', action = 'VACUOUS-PROBE-V3-1: rolled back by REM-A7-PAPERS-1' WHERE class = 'issue-100523' AND module = 'rem-a7-papers-v1'; UPDATE remediation_contracts SET verify_probe = 'SELECT ''closed'' AS expected, (SELECT CASE WHEN status IN (''closed'', ''resolved'') THEN ''closed'' ELSE NULL END FROM agent_issues WHERE id = 100575) AS observed', verify_transport = 'd1-query', status = 'superseded', last_verdict = 'superseded:rollback REM-A7-PAPERS-1', module = 'probe-template-v3-generic', action = 'VACUOUS-PROBE-V3-1: rolled back by REM-A7-PAPERS-1' WHERE class = 'issue-100575' AND module = 'rem-a7-papers-v1'; UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:rollback REM-A7-PAPERS-1' WHERE class = 'fm-reader-history-navigation-control'; UPDATE issue_triage SET close_evidence = NULL WHERE issue_id IN (100523, 100575) AND close_evidence LIKE '%rem-a7 F4%' AND triage_state = 'triaged'

UPDATE remediation_contracts
   SET precondition = 'living-paper holds the seven records of the audit table (Qubit Delusion series) as published papers',
       action = 'REM-A7-PAPERS-1: the seven records named by the audit are measured on living-paper (complete body, links, no registry identifier); a cut body fails the probe and the paper loops (qnfo-research-exec complete stage, COMPLETENESS-SWEEP-1) own the repair.',
       verify_probe = 'SELECT ''series 7 of 7 complete, short or empty published bodies 0, registry identifiers 0'' AS expected, CASE WHEN (SELECT COUNT(*) FROM papers p WHERE p.status = ''published'' AND p.slug IN (''shor-assumptions-audit'', ''paper-manifesto-honest-computation'', ''paper-the-qubit-delusion'', ''paper-beyond-the-qubit'', ''paper-physics-of-computation'', ''paper-problem-substrate-mapping'', ''paper-institutional-reform'') AND length(p.body_md) >= CASE p.slug WHEN ''shor-assumptions-audit'' THEN 13001 WHEN ''paper-manifesto-honest-computation'' THEN 23797 ELSE 20000 END AND instr(substr(p.body_md, length(p.body_md) / 2), ''Conclusion'') > 0 AND (length(p.body_md) - length(replace(p.body_md, ''## '', ''''))) / 3 >= 6 AND coalesce(p.pdf_path, '''') <> '''' AND coalesce(p.r2_path, '''') <> '''') = 7 AND (SELECT COUNT(*) FROM papers WHERE status = ''published'' AND (body_md IS NULL OR length(trim(body_md)) < 2000)) = 0 AND (SELECT COUNT(*) FROM papers WHERE status = ''published'' AND (coalesce(zenodo_doi, '''') <> '''' OR coalesce(zenodo_url, '''') <> '''' OR coalesce(doi, '''') LIKE ''10.5281%'')) = 0 THEN ''series 7 of 7 complete, short or empty published bodies 0, registry identifiers 0'' ELSE ''series '' || (SELECT COUNT(*) FROM papers p WHERE p.status = ''published'' AND p.slug IN (''shor-assumptions-audit'', ''paper-manifesto-honest-computation'', ''paper-the-qubit-delusion'', ''paper-beyond-the-qubit'', ''paper-physics-of-computation'', ''paper-problem-substrate-mapping'', ''paper-institutional-reform'') AND length(p.body_md) >= CASE p.slug WHEN ''shor-assumptions-audit'' THEN 13001 WHEN ''paper-manifesto-honest-computation'' THEN 23797 ELSE 20000 END AND instr(substr(p.body_md, length(p.body_md) / 2), ''Conclusion'') > 0 AND (length(p.body_md) - length(replace(p.body_md, ''## '', ''''))) / 3 >= 6 AND coalesce(p.pdf_path, '''') <> '''' AND coalesce(p.r2_path, '''') <> '''') || '' of 7 complete, short or empty published bodies '' || (SELECT COUNT(*) FROM papers WHERE status = ''published'' AND (body_md IS NULL OR length(trim(body_md)) < 2000)) || '', registry identifiers '' || (SELECT COUNT(*) FROM papers WHERE status = ''published'' AND (coalesce(zenodo_doi, '''') <> '''' OR coalesce(zenodo_url, '''') <> '''' OR coalesce(doi, '''') LIKE ''10.5281%'')) END AS observed',
       verify_transport = 'd1-query@living-paper', status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, last_attempt_at = NULL,
       module = 'rem-a7-papers-v1', next_due_at = datetime('now')
 WHERE class = 'issue-100523' AND instr(coalesce(action, ''), 'VACUOUS-PROBE-V3-1') = 1
   AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100523 AND a.status = 'open');

UPDATE remediation_contracts
   SET precondition = 'papers.qnfo.org serves stored predecessors of a published paper (paper_version_history) through /papers/<slug>/versions/<snapshot id>',
       action = 'REM-A7-PAPERS-1: the public reader serves a stored predecessor with an accurate capture-date caption; a regression of the snapshot route fails the probe and qnfo-gateway owns the repair.',
       verify_probe = '{"url": "https://papers.qnfo.org/papers/the-margolus-levitin-bound-and-energy-time-limits-for-quantum-computation-at-the/versions/146", "status": 200, "contains": "Capture time is not a publication date"}',
       verify_transport = 'runner-https', status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, last_attempt_at = NULL,
       module = 'rem-a7-papers-v1', next_due_at = datetime('now')
 WHERE class = 'issue-100575' AND instr(coalesce(action, ''), 'VACUOUS-PROBE-V3-1') = 1
   AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = 100575 AND a.status = 'open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, next_due_at)
VALUES ('fm-reader-history-navigation-control', NULL, 'a stable published control paper retains earlier snapshots in living-paper (the-margolus-levitin-bound, 2 snapshots)',
        'failure-mode detector (control sample of fm-reader-history-navigation): the public reader lists archived snapshots; an unexpected 404 or a missing archived flag files RUNTIME-PROBE-FAIL-1', '{"url": "https://papers.qnfo.org/api/paper-context/the-margolus-levitin-bound-and-energy-time-limits-for-quantum-computation-at-the", "status": 200, "contains": "\"archived\":true"}', 'runner-https', 3, 'qnfo-gateway', 1, 'active', 'reader-history-v1', 45000, 5, datetime('now'));

UPDATE issue_triage SET close_evidence = 'RESOLVED-ALREADY and SUPERSEDED-BY-DIRECTIVE, measured 2026-10-26 (rem-a7 F4). Gap C-01 is the Vast World audit''s finding (section 4.1 and 4.2, 2026-07-19) that at least 3 D1 paper bodies were cut off (Manifesto at section 2, Qubit Delusion, Beyond the Qubit, Physics of Computation at 2.3, Shor''s Assumptions body missing). (1) The seven records of that table are now complete on living-paper, all status published: shor-assumptions-audit 13,001 chars (the audit''s recovered count 13,001), paper-manifesto-honest-computation 23,877 (audit 23,797), paper-the-qubit-delusion 49,634, paper-beyond-the-qubit 58,257, paper-physics-of-computation 30,834, paper-problem-substrate-mapping 32,679, paper-institutional-reform 36,359; each has a Conclusion in the second half of its body, and its page papers.qnfo.org/papers/<slug> answers 200 with 10 to 13 level-2 sections ending at the conclusion (physics-of-computation lists sections 1 to 7, the audit had it cut at 2.3; the Manifesto carries its Falsification Pledge). (2) Each row links its full text outside the body column: r2_path releases/2026/07/<slug>.md and pdf_path pdf/<slug>.pdf on all seven (pdf_path on 704 of 704 published rows, r2_path on 437). (3) D1 does not cut bodies: of 704 published papers none is empty or under 2,000 chars, no body length is shared by 4 or more rows (a cap would show as one repeated length), the longest is 747,239 chars. (4) ''DOIs as the canonical full text'' is superseded by owner directive NOZ-DOI-1 (2026-10-10: the deposit registrar account is closed, every 10.5281 DOI is dead): 0 of 704 published rows carry doi, zenodo_doi or zenodo_url, and the audit''s own table already points each record at its papers.qnfo.org address, which is the canonical full-text source. (5) The systemic cause, a generator stopping at its output cap, is closed by PAPER-COMPLETE-1 (qnfo-research-exec 0.14.0, 2026-10-12: complete stage, no length cap) and checked daily by COMPLETENESS-SWEEP-1 (cloud_ops_events completeness-sweep 2026-10-26T03:01:21Z: scanned 78, truncated 13 of which 9 summary-only citations, queued 0, skipped 13); that backlog belongs to the research loops, not to the audit''s seven records. Probe (class issue-100523, d1-query@living-paper): series 7 of 7 complete (published, length at or above the recovered count or 20,000, Conclusion in the second half, 6 or more level-2 headings, r2_path and pdf_path set), 0 short or empty published bodies, 0 registry identifiers; it reads that sentence now and names the failing count when a record is cut.'
 WHERE issue_id = 100523 AND coalesce(close_evidence, '') = ''
   AND EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = 'issue-100523' AND c.module = 'rem-a7-papers-v1');

UPDATE issue_triage SET close_evidence = 'FINDINGS and FIX VERIFIED LIVE, 2026-10-26 (rem-a7 F4; the fix itself is qnfo-gateway 3.43.x, PR 4167 and migrations/2026-10-25-reader-history-evidence.sql, by session copilot-af0ed947-us10). (1) Where previous versions are stored: living-paper.paper_version_history (342 snapshots over 229 slugs, 2026-09-03 to 2026-10-26; columns id, slug, version, title, abstract, body_md, archived_at, superseded_by; unique on slug and version), written by the triggers papers_version_archive_upd and papers_version_archive_ver when papers.body_md or papers.version changes; the current text stays in papers. (2) Why the Versions tab did not list them: handlePaperContext listed same-title current papers only and never read paper_version_history; example direction-of-epistemic-risk-as-a-criterion-distinguishing-science-from-numerolog showed only current 1.1.1 although snapshots 40 (1.0.0, 24,510 chars) and 160 (1.1.0, 26,163 chars) exist (snapshot 269 is 1.1.1, 26,342 chars). (3) Why displayed dates disagreed with version dates: archived_at is the time the snapshot row was written, not the version''s publication or revision date; snapshot 40 (version 1.0.0) reads 2026-10-20T09:41:23.251Z, later than snapshot 160 (version 1.1.0) 2026-10-20 09:31:08, in two timestamp formats, so capture order is not version order; created_at is the row''s creation and last_revised_at is set by the version trigger. Fix on main: handlePaperContext now reads paper_version_history (ORDER BY id DESC LIMIT 50) and returns the current paper (date_kind revised, published or created) plus each snapshot (snapshot_id, date_kind archived, archived_at, superseded_by, url /papers/<slug>/versions/<id>); the snapshot page is text/plain, no-store, nosniff and says ''Capture time is not a publication date''. Live reads 2026-10-26 18:0xZ: /api/paper-context/the-margolus-levitin-bound-and-energy-time-limits-for-quantum-computation-at-the lists current 2.0.3 plus snapshots 146 (2.0.1, captured 2026-09-11 09:02:07) and 145 (2.0.0, 2026-09-05 12:37:28); /papers/the-margolus-levitin-bound-and-energy-time-limits-for-quantum-computation-at-the/versions/146 answers 200, 8,613 bytes, with that caption; the paper page shows ''Living paper v2.0.3, 3 versions'' with its Versions tab; isolation: /api/paper-context for the quarantined chapter-5-the-contours-of-ignorance 404, an unknown slug 404, snapshot 999999 404, the snapshot route of a quarantined slug 404; offline suites qnfo-gateway reader-versions-acceptance, paper-history-acceptance and private-isolation-acceptance pass. Out of scope by the issue''s own text: historical-body reproduction beyond the snapshot page. Probe (class issue-100575, runner-https): the snapshot page answers 200 and carries the capture-date caption; detector fm-reader-history-navigation (API metadata) stays, and fm-reader-history-navigation-control adds a stable published control paper, so the sample paper''s own status no longer decides the detector.'
 WHERE issue_id = 100575 AND coalesce(close_evidence, '') = ''
   AND EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = 'issue-100575' AND c.module = 'rem-a7-papers-v1');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a7-f4',
  'an owner task whose condition is already met is closed by a probe that measures the condition and would fail on a regression, not by a status flip; a placeholder probe that observes nothing is replaced, not kept',
  'REM-A7-PAPERS-1: contracts issue-100523 (d1-query@living-paper) and issue-100575 (runner-https) rewritten to measure their definitions of done; control detector fm-reader-history-navigation-control added; findings staged as close_evidence',
  'living-paper 2026-10-26: seven series records complete (13,001 to 58,257 chars), 0 of 704 published rows with a registry identifier, none under 2,000 chars; papers.qnfo.org snapshot 146 answers 200 with the capture-date caption; paper_version_history 342 snapshots over 229 slugs',
  'applied by migration', 'two contracts rewritten, one detector contract added, two close_evidence texts staged; no worker, paper or secret changed',
  'the Rollback line of migrations/2026-10-26-rem-a7-papers.sql',
  'the two issues close through their own measuring probes (remediation_verification_autoclose_ins) and reopen through REMEDIATION-REOPEN-2 if a record is cut or the snapshot route regresses',
  'issues 100523 and 100575 closed by the first passing verification (the consumer runs due contracts hourly); a cut series record or a lost snapshot route reopens them',
  'research and reach: papers.qnfo.org stays a complete, versioned, identifier-honest reader',
  'GET of the seven series pages, the api/paper-context and snapshot routes, four isolation routes; D1 reads of living-paper (bodies, links, identifiers); the probe SQL against live living-paper returned its expected sentence'
WHERE NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.action LIKE 'REM-A7-PAPERS-1:%');
